@test
def t_kmeans():
    X, y = blobs(60, 3, 4)
    c, idx = kmeans_plusplus(X, 4, random_state=0)
    assert same(idx, pp_idx)
    a = KMeans(n_clusters=4, random_state=0).fit(X)
    assert close(a.cluster_centers_, km_a_centers, 1e-10, 1e-12) and same(a.labels_, km_a_labels)
    assert close([a.inertia_], [km_a_inertia], 1e-10) and a.n_iter_ == km_a_iter
    b = KMeans(n_clusters=3, init="random", n_init=5, random_state=42).fit(X)
    assert close(b.cluster_centers_, km_b_centers, 1e-10, 1e-12) and same(b.labels_, km_b_labels)
    assert close([b.inertia_], [km_b_inertia], 1e-10) and b.n_iter_ == km_b_iter
    c5 = KMeans(n_clusters=5, random_state=1, algorithm="elkan", max_iter=3).fit(X)
    assert close(c5.cluster_centers_, km_c_centers, 1e-10, 1e-12) and same(c5.labels_, km_c_labels)
    assert close([c5.inertia_], [km_c_inertia], 1e-10) and c5.n_iter_ == km_c_iter
    d = KMeans(n_clusters=4, n_init=3, random_state=7, tol=0.0).fit(X)
    assert close(d.cluster_centers_, km_d_centers, 1e-10, 1e-12) and same(d.labels_, km_d_labels)
    assert close([d.inertia_], [km_d_inertia], 1e-10) and d.n_iter_ == km_d_iter
    assert same(a.predict(X[:7] + 0.3), km_pred)
    assert close(a.transform(X[:5]), km_tr, 1e-10, 1e-12)
    assert close([a.score(X[:10])], [km_score], 1e-10)
    init = np.ascontiguousarray(X[:4])
    e = KMeans(n_clusters=4, init=init, n_init=1).fit(X)
    assert close(e.cluster_centers_, km_arr_centers, 1e-10, 1e-12) and e.n_iter_ == km_arr_iter
    sw = np.array([1.0 + (i % 3) for i in range(60)])
    f = KMeans(n_clusters=3, random_state=3).fit(X, sample_weight=sw)
    assert close(f.cluster_centers_, km_sw_centers, 1e-10, 1e-12) and close([f.inertia_], [km_sw_inertia], 1e-10)
    assert same(KMeans(n_clusters=4, random_state=0).fit_predict(X), km_a_labels)

@test
def t_dbscan():
    X, y = blobs(60, 3, 4)
    e = DBSCAN(eps=1.3, min_samples=4).fit(X)
    assert same(e.labels_, db_e_labels) and same(e.core_sample_indices_, db_e_core)
    m = DBSCAN(eps=2.2, min_samples=4, metric="manhattan").fit(X)
    assert same(m.labels_, db_m_labels) and same(m.core_sample_indices_, db_m_core)
    c = DBSCAN(eps=1.0, min_samples=4, metric="chebyshev").fit(X)
    assert same(c.labels_, db_c_labels) and same(c.core_sample_indices_, db_c_core)
    k = DBSCAN(eps=1.2, min_samples=4, metric="minkowski", p=3.0).fit(X)
    assert same(k.labels_, db_k_labels) and same(k.core_sample_indices_, db_k_core)

@test
def t_agglomerative():
    X2, _ = blobs(40, 2, 3)
    w = AgglomerativeClustering(n_clusters=3, linkage="ward", compute_distances=True).fit(X2)
    assert same(w.labels_, ag_ward_labels) and same(w.children_, ag_ward_children) and close(w.distances_, ag_ward_dist, 1e-10, 1e-12)
    c = AgglomerativeClustering(n_clusters=3, linkage="complete", compute_distances=True).fit(X2)
    assert same(c.labels_, ag_complete_labels) and same(c.children_, ag_complete_children) and close(c.distances_, ag_complete_dist, 1e-10, 1e-12)
    a = AgglomerativeClustering(n_clusters=3, linkage="average", compute_distances=True).fit(X2)
    assert same(a.labels_, ag_average_labels) and same(a.children_, ag_average_children) and close(a.distances_, ag_average_dist, 1e-10, 1e-12)
    s = AgglomerativeClustering(n_clusters=3, linkage="single", compute_distances=True).fit(X2)
    assert same(s.labels_, ag_single_labels) and same(s.children_, ag_single_children) and close(s.distances_, ag_single_dist, 1e-10, 1e-12)
    t = AgglomerativeClustering(n_clusters=None, distance_threshold=2.0, linkage="average", metric="manhattan").fit(X2)
    assert same(t.labels_, ag_thr_labels) and t.n_clusters_ == ag_thr_n

def check_metrics(X, lt: List[int], b: List[int], e: List[float], hcv: List[float], cm: List[int]):
    assert close([adjusted_rand_score(lt, b), rand_score(lt, b), mutual_info_score(lt, b),
                  adjusted_mutual_info_score(lt, b), normalized_mutual_info_score(lt, b),
                  normalized_mutual_info_score(lt, b, average_method="geometric")], e[:6], 1e-10, 1e-13)
    h, c, v = homogeneity_completeness_v_measure(lt, b)
    assert close([h, c, v], hcv, 1e-10, 1e-13)
    assert close([fowlkes_mallows_score(lt, b)], e[6:7], 1e-10, 1e-13)
    assert same(contingency_matrix(lt, b), cm)
    assert close([silhouette_score(X, b), silhouette_score(X, b, metric="manhattan"),
                  calinski_harabasz_score(X, b), davies_bouldin_score(X, b)], e[7:], 1e-10, 1e-13)

@test
def t_metrics():
    X, y = blobs(60, 3, 4)
    lt = [i % 4 for i in range(60)]
    lp = [int(v) for v in KMeans(n_clusters=5, random_state=0).fit(X).labels_]
    lp2 = [(i * 7) % 3 for i in range(60)]
    check_metrics(X, lt, lp, [ari1, ri1, mi1, ami1, nmi1, nmig1, fm1, sil1, silm1, ch1, db1], hcv1, cm1)
    check_metrics(X, lt, lp2, [ari2, ri2, mi2, ami2, nmi2, nmig2, fm2, sil2, silm2, ch2, db2], hcv2, cm2)
    assert close(silhouette_samples(X, lp)[:12], sils, 1e-10, 1e-13)

t_kmeans()
t_dbscan()
t_agglomerative()
t_metrics()
